const STATIC_FILES = STATIC_ASSETS.map(asset => asset.path);
const SCOPE = new URL(self.registration.scope);
const CACHE_PREFIX = 'study-review-static:' + encodeURIComponent(SCOPE.pathname) + ':';
const CACHE_NAME = CACHE_PREFIX + BUILD;
const HOME = new URL('./index.html', SCOPE).href;
const ALLOWED = new Set(STATIC_FILES.map(file => new URL(file, SCOPE).href));

function precacheURL(key) {
  // Vercel commonly normalizes index.html to its directory's public URL.
  if (key === HOME) return SCOPE.href;
  return key.endsWith('/index.html') ? key.slice(0, -'/index.html'.length) : key;
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const existed = (await caches.keys()).includes(CACHE_NAME);
    try {
      // Existing same-origin authentication may unlock a protected static preview.
      // No bypass: URL, HTTP 200, MIME, size and exact build SHA-256 must ALL match.
      const responses = await Promise.all(STATIC_ASSETS.map(async asset => {
        const key = new URL(asset.path, SCOPE).href;
        const response = await fetch(new Request(precacheURL(key), {
          credentials: 'same-origin', cache: 'no-store', mode: 'same-origin', redirect: 'follow'
        }));
        const finalURL = new URL(response.url);
        const finalKey = key.endsWith('.html') ? navigationKey(finalURL) : staticKey(finalURL);
        if (response.status !== 200 || finalURL.origin !== SCOPE.origin || !finalURL.pathname.startsWith(SCOPE.pathname) || finalURL.search || finalURL.hash || finalKey !== key) {
          throw new Error('Invalid offline asset response');
        }
        const mime = (response.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
        if (!asset.mime.includes(mime)) throw new Error('Invalid offline asset MIME');
        const bytes = await response.arrayBuffer();
        if (bytes.byteLength !== asset.size) throw new Error('Offline asset integrity mismatch');
        const digest = await crypto.subtle.digest('SHA-256', bytes);
        const actual = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
        if (actual !== asset.sha256) throw new Error('Offline asset integrity mismatch');
        // Rebuild only safe static headers. Never persist auth/session headers or
        // redirect metadata; even HTML is accepted only when byte-identical to this build.
        const textual = asset.mime[0].startsWith('text/') || ['application/json', 'application/manifest+json', 'image/svg+xml'].includes(asset.mime[0]);
        const contentType = asset.mime[0] + (textual ? '; charset=utf-8' : '');
        return [key, new Response(bytes, { status: 200, headers: { 'Content-Type': contentType, 'X-Content-Type-Options': 'nosniff' } })];
      }));
      const cache = await caches.open(CACHE_NAME);
      await Promise.all(responses.map(([key, response]) => cache.put(key, response)));
    } catch (error) {
      // A failed install never leaves a partial new build or replaces the active worker.
      if (!existed) await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
  // Do not skipWaiting: keep an already-open page and its assets on one build.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

function staticKey(url) {
  // Existing script/style version labels map to their precached static file.
  // Other query parameters are ignored by this worker, never stored or normalized.
  const keys = Array.from(url.searchParams.keys());
  if (keys.length && (keys.length !== 1 || keys[0] !== 'v' || !/^[a-zA-Z0-9._-]{1,80}$/.test(url.searchParams.get('v')))) return null;
  const clean = new URL(url.href); clean.search = ''; clean.hash = '';
  return ALLOWED.has(clean.href) ? clean.href : null;
}

function navigationKey(url) {
  const clean = new URL(url.href); clean.search = ''; clean.hash = '';
  // Query values are never cached; a published HTML shell is safe to reuse.
  if (clean.pathname.endsWith('.html') && ALLOWED.has(clean.href)) return clean.href;
  const directory = new URL(clean.href);
  if (!directory.pathname.endsWith('/')) directory.pathname += '/';
  directory.pathname += 'index.html';
  if (ALLOWED.has(directory.href)) return directory.href;
  // Also accept a host's clean URL for a standalone .html page, when that file exists.
  if (!clean.pathname.endsWith('/')) {
    clean.pathname += '.html';
    if (ALLOWED.has(clean.href)) return clean.href;
  }
  return null;
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const key = staticKey(url);
  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE_NAME);
      const page = navigationKey(url);
      if (page) { const saved = await cache.match(page); if (saved) return saved; }
      try { return await fetch(request); }
      catch (_) { return (await cache.match(HOME)) || Response.error(); }
    })());
  } else if (key) {
    event.respondWith(caches.open(CACHE_NAME).then(async cache => (await cache.match(key)) || fetch(request)));
  }
  // No runtime cache writes: responses, quiz results, private APIs, authentication,
  // and cross-origin resources can never enter this static cache.
});
